using System.Diagnostics;
using System.Reflection;
using System.Security.Cryptography;
using System.Text.Json;
using MphRead;
using MphRead.Formats;
using MphRead.Mods;
using MphRead.Mods.CustomWeapons.Packages;
using MphRead.Mods.Network;
using MphRead.Mods.Render;
using MphRead.Mods.Replay;
using MphRead.Sound;
using OpenTK.Graphics.OpenGL;
using OpenTK.Mathematics;
using OpenTK.Windowing.Desktop;

internal static class CustomReplayPlayerChecks
{
    internal static int Run(string input,string output)
    {
        string cwd=Directory.GetCurrentDirectory();NativeWindow? window=null;DesktopGraphicsSession? graphics=null;
        try
        {
            input=Path.GetFullPath(input);output=Path.GetFullPath(output);Directory.CreateDirectory(output);string loaded=typeof(PassiveReplayPlayer).Assembly.Location;Console.WriteLine("Loaded ProjectPrime: "+loaded+" SHA256="+Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(loaded))));string data=File.ReadAllText(Path.Combine(input,"replay-fixture-data.txt"));Directory.SetCurrentDirectory(data);Paths.UpdatePaths();Paths.ChooseMphPath();MapAudit.ForceEveryone=true;
            var foreground=GameState.Current;var random=Rng.Current;uint rng1=Rng.Rng1,rng2=Rng.Rng2;bool globalReplay=DemoPlayback.IsActive,globalNetwork=NetSession.Active;
            string archive=Path.Combine(input,"actual-full-custom"+DemoFile.Extension);using var json=JsonDocument.Parse(File.ReadAllBytes(Path.Combine(input,"file-expected-worlds.json")));var rows=json.RootElement.EnumerateArray().Select(row=>(Name:row.GetProperty("name").GetString()!,Frame:row.GetProperty("frame").GetUInt32(),File:row.GetProperty("filename").GetString()!)).ToArray();if(rows.Length is <1 or >8)throw new InvalidDataException("Bounded actual target list required.");uint origin=rows.Single(row=>row.Name=="baseline").Frame,end=rows.Single(row=>row.Name=="end").Frame;byte[] package=File.ReadAllBytes(Path.Combine(input,"variant.ppweapon"));if(package.Length>32*1024*1024)throw new InvalidDataException("Package bound.");var parsed=WeaponPackage.Parse(package);string storeRoot=Path.Combine(output,"store");var store=new WeaponPackageStore(storeRoot);store.Install(package);
            var settings=DesktopGlContext.Settings(background:true);settings.ClientSize=new(640,480);settings.StartVisible=true;settings.Title="Bounded private custom replay player";window=new NativeWindow(settings);graphics=new DesktopGraphicsSession(window);
            int checks=0,updates=0,stepsObserved=0,replacements=0,maxSteps=0;void Check(bool ok,string label){if(!ok)throw new InvalidDataException(label);checks++;}var updateRows=new List<object>();var workField=typeof(PassiveReplayPlayer).GetField("_customWork",BindingFlags.Instance|BindingFlags.NonPublic)!;var works=new HashSet<Task>();
            int Update(PassiveReplayPlayer player,int budget=7,double milliseconds=5){int before=stepsObserved;int steps=player.Update(budget,milliseconds);updates++;maxSteps=Math.Max(maxSteps,steps);Check(steps>=0&&steps<=Math.Min(120,Math.Max(1,budget))&&stepsObserved-before==steps,"one Update respects requested/120 fixed-step bound and step notifications");if(workField.GetValue(player) is Task work)works.Add(work);Check(works.Count(work=>!work.IsCompleted)<=1,"at most one asynchronous package/world preparation is unfinished");if(updateRows.Count<8192)updateRows.Add(new{updates,steps,frame=player.Current.Session.CurrentFrame,recordingFrame=player.Current.Session.RecordingFrame,player.Ready,player.SeekSimulationSteps});return steps;}
            void Ready(PassiveReplayPlayer player,bool observeSeek=false){var watch=Stopwatch.StartNew();if(observeSeek)Update(player);while(!player.Ready){if(watch.Elapsed.TotalSeconds>30)throw new TimeoutException("Bounded custom player seek did not settle.");if(Update(player)==0)Thread.Sleep(1);}}
            void Compare(PassiveReplayPlayer player,(string Name,uint Frame,string File) row,string label){using var expected=ReplayWorldCheckpoint.FromCustomBytes(File.ReadAllBytes(Path.Combine(input,row.File)));using var actual=ReplayWorldCheckpoint.CaptureCustom(player.Current);var differences=expected.CanonicalGraphDifferences(actual);File.WriteAllText(Path.Combine(output,label+"-differences.json"),JsonSerializer.Serialize(differences));Check(differences.Length==0&&player.Current.Session.RecordingFrame==row.Frame&&player.Current.Session.CurrentFrame==row.Frame-origin,"actual player exact whole-world and relative/absolute clock parity "+label);}
            using(var baselineReader=DemoReader.Open(archive,out var baselineResult))
            using(var baselinePrepared=Task.Run(()=>PreparedCustomReplayArchive.Prepare(archive,store,origin)).GetAwaiter().GetResult())
            {
                Check(baselineReader!=null&&baselineResult==ReplayOpenResult.Success,"actual archive baseline available for detached gate checks");var metadata=baselineReader!.Metadata!;byte[] originalWorld=metadata.WorldCheckpoint.ToArray();
                ReplayMetadata Expected(uint? recordingOrigin=null,GameMode? mode=null,byte[]? world=null,ulong? map=null,string? room=null,bool changeIndexed=false,bool omitDescriptor=false)=>new(){ProtocolVersion=metadata.ProtocolVersion,FormatVersion=metadata.FormatVersion,OriginRecordingFrame=recordingOrigin??metadata.OriginRecordingFrame,RoomKey=room??metadata.RoomKey,Mode=mode??metadata.Mode,MapHash=map??metadata.MapHash,IndexedFireContinuation=changeIndexed?!(metadata.IndexedFireContinuation??false):metadata.IndexedFireContinuation,TimedShotCertificates=metadata.TimedShotCertificates,CustomWeapons=omitDescriptor?null:metadata.CustomWeapons,WorldCheckpoint=world??originalWorld.ToArray()};
                Check(baselinePrepared.MatchesArchiveBaseline(Expected(),baselineReader.DurationFrames),"exact detached actual metadata and duration match admitted baseline");Check(!baselinePrepared.MatchesArchiveBaseline(Expected(),checked(baselineReader.DurationFrames+1)),"wrong archive duration refuses baseline match");Check(!baselinePrepared.MatchesArchiveBaseline(Expected(recordingOrigin:checked(metadata.OriginRecordingFrame+1)),baselineReader.DurationFrames),"different absolute origin refuses baseline match");Check(!baselinePrepared.MatchesArchiveBaseline(Expected(mode:metadata.Mode==GameMode.Battle?GameMode.Survival:GameMode.Battle),baselineReader.DurationFrames),"different recorded mode refuses baseline match");byte[] otherWorld=originalWorld.ToArray();otherWorld[^1]^=1;Check(!baselinePrepared.MatchesArchiveBaseline(Expected(world:otherWorld),baselineReader.DurationFrames),"different privately owned initial-world bytes refuse baseline match");Check(!baselinePrepared.MatchesArchiveBaseline(Expected(map:metadata.MapHash^1),baselineReader.DurationFrames),"different exact map content hash refuses baseline match");Check(!baselinePrepared.MatchesArchiveBaseline(Expected(room:metadata.RoomKey+" different"),baselineReader.DurationFrames),"different room refuses baseline match");Check(!baselinePrepared.MatchesArchiveBaseline(Expected(changeIndexed:true),baselineReader.DurationFrames),"different indexed presentation capability refuses baseline match");Check(!baselinePrepared.MatchesArchiveBaseline(Expected(omitDescriptor:true),baselineReader.DurationFrames),"missing exact custom descriptor refuses baseline match");Check(metadata.WorldCheckpoint.SequenceEqual(originalWorld)&&baselinePrepared.MatchesArchiveBaseline(metadata,baselineReader.DurationFrames),"negative comparisons never mutate actual metadata or prepared baseline");
            }
            uint far=end-1;using(var prepared=Task.Run(()=>PreparedCustomReplayArchive.Prepare(archive,store,far)).GetAwaiter().GetResult())
            {
                using var selected=prepared.CopyWorld();using var player=PassiveReplayPlayer.OpenCustomArchive(prepared,storeRoot,new Vector2i(640,480));prepared.Dispose();player.Stepped+=_=>stepsObserved++;player.Replaced+=(_,_)=>replacements++;Check(selected.Frame<far,"actual far target requires genuine forward reconstruction beyond selected durable world");Check(player.Current.Session.RecordingFrame==selected.Frame&&!player.Current.HasStepped,"opening a far prepared target performs zero eager reconstruction steps");Check(store.Uninstall(parsed.PackageHash)&&store.Prune()==0,"player retains exact historical package independently after preparation disposal/uninstall");Check(Update(player,int.MaxValue,0)==1,"zero time budget permits one progress step while retaining fixed-step bound");Ready(player);Check(player.Current.Session.RecordingFrame==far,"bounded initial warm-up reaches requested absolute target");
                foreach(var row in rows.Reverse())
                {
                    player.Seek(row.Frame-origin);Ready(player,observeSeek:true);Compare(player,row,"seek-"+row.Name);player.Transport.Pause();uint paused=player.Current.Session.CurrentFrame;Check(Update(player)==0&&player.Current.Session.CurrentFrame==paused,"paused player performs no simulation step");
                    for(int draw=0;draw<2;draw++){using var before=ReplayWorldCheckpoint.CaptureCustom(player.Current);var actor=player.Current.Scene.Players.Items[0];var aim=actor.Position+Vector3.UnitY;player.Current.Scene.SetReplicaCamera(aim+new Vector3(2.7f,1.2f,3.8f),aim,55);player.Current.Scene.OnResize();player.Current.Scene.OnDrawFrame();Check(player.Current.Scene.OnRenderFrame()&&GL.GetError()==OpenTK.Graphics.OpenGL.ErrorCode.NoError,"actual bounded player Scene draws");DesktopGraphicsSession.Present(window);player.Current.Scene.AfterRenderFrame();using var after=ReplayWorldCheckpoint.CaptureCustom(player.Current);Check(before.CanonicalGraphDifferences(after).Length==0,"strict graph unchanged by bounded-player picture");}
                    // Continue with actual file facts and compare each observed complete-frame target.
                    player.Transport.Play();player.Transport.SetPlaybackRate(4);var watch=Stopwatch.StartNew();while(!player.Current.Session.AtEnd){if(watch.Elapsed.TotalSeconds>30)throw new TimeoutException("Actual suffix did not reach EOF.");Update(player,1);foreach(var target in rows.Where(target=>target.Frame==player.Current.Session.RecordingFrame))Compare(player,target,"suffix-"+row.Name+"-to-"+target.Name);}Check(player.Transport.AtEnd&&Update(player)==0,"EOF transport and repeated Update remain inert");
                }
                player.Transport.Restart();Ready(player,observeSeek:true);Check(player.Current.Session.CurrentFrame<=7,"restart resumes from a bounded initial-origin update");player.Seek(0,resume:false);Ready(player,observeSeek:true);Check(player.Current.Session.CurrentFrame==0,"explicit paused seek restores exact relative origin");player.Transport.Pause();player.Transport.StepForward();Check(Update(player)==1&&player.Current.Session.CurrentFrame==1&&player.Transport.IsPaused,"single-step advances one actual frame and stays paused");player.Transport.SetPlaybackRate(4);player.Transport.Play();Check(Update(player,120)==4&&player.Current.Session.CurrentFrame==5,"4x playback schedules four ordinary fixed steps");player.Transport.Pause();
                var retained=player.Current;uint retainedFrame=retained.Session.CurrentFrame;using var beforeStale=ReplayWorldCheckpoint.CaptureCustom(retained);using(var gate=new FileStream(Path.Combine(storeRoot,".store.lock"),FileMode.Open,FileAccess.ReadWrite,FileShare.None))
                {
                    player.Seek(end-origin,resume:false);Update(player,1,1);var pending=workField.GetValue(player) as Task;Check(pending!=null&&ReferenceEquals(retained,player.Current),"current Scene stays presented while real store gate blocks worker preparation");player.Seek(end-origin,resume:true);Update(player,1,1);Check(ReferenceEquals(pending,workField.GetValue(player)),"same pending target changes resume preference without duplicate worker");player.Seek(end-origin,resume:false);Update(player,1,1);Check(ReferenceEquals(pending,workField.GetValue(player)),"repeated pending target retains single preparation when pausing preference");player.Seek(0);Update(player,1,1);player.Seek(retainedFrame,resume:false);Update(player,1,1);Check(ReferenceEquals(retained,player.Current)&&player.Current.Session.CurrentFrame==retainedFrame,"rapid stale requests keep healthy Scene until admitted same-current replacement");
                }
                Ready(player,observeSeek:true);using(var afterStale=ReplayWorldCheckpoint.CaptureCustom(player.Current))Check(!ReferenceEquals(retained,player.Current)&&player.Current.Session.CurrentFrame==retainedFrame&&player.Transport.IsPaused&&beforeStale.CanonicalGraphDifferences(afterStale).Length==0,"same-current seek rebinds fresh exact world and ignores retired worker goals");
            }
            bool Pruned(){var watch=Stopwatch.StartNew();while(store.Prune()==0){if(watch.Elapsed.TotalSeconds>5)return false;Thread.Sleep(5);}return true;}Check(Pruned(),"player and retired-worker disposal release last actual historical archive lease");
            for(int repeat=0;repeat<2;repeat++){store.Install(package);using(var prepared=Task.Run(()=>PreparedCustomReplayArchive.Prepare(archive,store)).GetAwaiter().GetResult())using(var player=PassiveReplayPlayer.OpenCustomArchive(prepared,storeRoot,new Vector2i(640,480))){prepared.Dispose();Check(store.Uninstall(parsed.PackageHash)&&store.Prune()==0,"repeated open owns independent retained resources");}Check(Pruned(),"repeated close releases reader Scene and package owner");}
            Check(ReferenceEquals(foreground,GameState.Current)&&ReferenceEquals(random,Rng.Current)&&rng1==Rng.Rng1&&rng2==Rng.Rng2&&globalReplay==DemoPlayback.IsActive&&globalNetwork==NetSession.Active,"bounded private player leaves foreground game RNG replay and network owners untouched");
            File.WriteAllText(Path.Combine(output,"player-results.json"),JsonSerializer.Serialize(new{checks,updates,stepsObserved,replacements,maxSteps,workers=works.Count,updateRows,scope="Explicit bounded private player over actual ordinary recorded file. Zero eager reconstruction, complete-world seek/draw/suffix parity, transport controls, stale worker cancellation and real lease ownership. Ordinary theatre UI remains outside this test."},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"PASS {checks} bounded custom replay player checks");return 0;
        }
        catch(Exception error){Console.Error.WriteLine("CUSTOM REPLAY PLAYER FAIL "+error);return 1;}
        finally{AudioLifetime.Shutdown();graphics?.Dispose();window?.Dispose();Directory.SetCurrentDirectory(cwd);}
    }
}
